// File: src/components/ReferralHistoryTable.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://192.168.1.170:8080"; // Mobile / Expo friendly IP

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchReferralHistory();
  }, []);

  const fetchReferralHistory = async () => {
    setLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem("authToken");
      if (!token) throw new Error("Authentication token not found");

      const res = await axios.get(`${API_BASE_URL}/bonus/history`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      // Filter only Referral bonuses
      const referralData = res.data.filter(item => item.type?.toLowerCase() === "referral");

      // Sort by newest first
      referralData.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

      setReferrals(referralData);
    } catch (err) {
      console.error("Error fetching referral history:", err);
      setError(err.message || "Failed to load referral history");
    } finally {
      setLoading(false);
    }
  };

  if (loading)
    return (
      <p className="text-center text-gray-500 py-6 text-lg">Loading referral history...</p>
    );

  if (error)
    return (
      <p className="text-center text-red-500 py-6 text-lg">{error}</p>
    );

  if (referrals.length === 0)
    return (
      <p className="text-center text-gray-500 py-6 text-lg">No referral bonuses yet.</p>
    );

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
      <h2 className="text-3xl font-bold text-center text-gray-800 mb-6">
        Referral Bonus History
      </h2>
      <div className="overflow-x-auto">
        <table className="min-w-full border border-gray-200 shadow-lg rounded-lg overflow-hidden">
          <thead className="bg-gray-100">
            <tr>
              <th className="py-3 px-6 text-left text-gray-700 font-semibold">#</th>
              <th className="py-3 px-6 text-left text-gray-700 font-semibold">
                Game ID / Referrer
              </th>
              <th className="py-3 px-6 text-left text-gray-700 font-semibold">
                Bonus Amount
              </th>
              <th className="py-3 px-6 text-left text-gray-700 font-semibold">Date</th>
            </tr>
          </thead>
          <tbody>
            {referrals.map((item, index) => (
              <tr
                key={index}
                className={`${
                  index % 2 === 0 ? "bg-white" : "bg-gray-50"
                } hover:bg-gray-100 transition-colors`}
              >
                <td className="py-3 px-6 text-gray-800">{index + 1}</td>
                <td className="py-3 px-6 text-gray-800 font-medium">
                  {item.sourceGameId || "N/A"}
                </td>
                <td className="py-3 px-6 text-green-600 font-bold">
                  {Number(item.amount).toLocaleString()} ৳
                </td>
                <td className="py-3 px-6 text-gray-500">
                  {new Date(item.createdAt).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
